async function loadUser(id: number): Promise<any> {
  const r = await fetch('/api/users/' + id);
  if (!r.ok) {
    throw new Error('bad status ' + r.status);
  }
  const u = await r.json();
  const r2 = await fetch('/api/orgs/' + u.orgId);
  const o = await r2.json();
  u.org = o;
  return u;
}

async function loadUsers(ids: number[]): Promise<any[]> {
  const out: any[] = [];
  for (let i = 0; i < ids.length; i++) {
    out[i] = await loadUser(ids[i]);
  }
  return out;
}

module.exports = { loadUser, loadUsers };
